def parse_csv_line(line):
    fields = []
    current = []
    in_quotes = False
    index = 0
    while index < len(line):
        ch = line[index]
        if in_quotes:
            if ch == '"':
                in_quotes = False
            else:
                current.append(ch)
        elif ch == ',':
            if current:
                fields.append(''.join(current))
            current = []
        else:
            current.append(ch)
        index += 1
    if current:
        fields.append(''.join(current))
    return fields
